local Fletcher = {}
local PRODUCTS = {
    arrow = { name = "Puščica", woodCost = 1, metalCost = 1, featherCost = 1, time = 1, cost = 5, attack = 10, description = "Standardna puščica." },
    bodkin = { name = "Oklepna puščica", woodCost = 1, metalCost = 2, featherCost = 1, time = 2, cost = 12, attack = 15, armorPierce = 10, description = "Za preboj oklepa." },
    crossbow_bolt = { name = "Samostrelska puška", woodCost = 2, metalCost = 2, time = 2, cost = 15, attack = 20, description = "Težki samostrelski izstreljek." },
    fire_arrow = { name = "Ognjena puščica", woodCost = 1, metalCost = 1, featherCost = 1, oilCost = 1, time = 3, cost = 20, attack = 12, fireDamage = 15, description = "Z ognjeno glavo." },
    quiver = { name = "Tulec", leatherCost = 2, woodCost = 1, time = 3, cost = 30, capacity = 20, description = "Tulec za puščice." },
    poisoned_arrow = { name = "Strupena puščica", woodCost = 1, metalCost = 1, featherCost = 1, poisonCost = 1, time = 5, cost = 50, attack = 10, poisonDamage = 20, description = "Strupena za atentate." },
}
local BUILDINGS = {
    workshop = { name = "Puščičarska delavnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    fletchery = { name = "Puščičarna", cost = { gold = 600, wood = 200, iron = 50 }, upkeep = 15, qualityBonus = 15 },
    arrow_forge = { name = "Kovašnica puščic", cost = { gold = 1500, wood = 300, stone = 200, iron = 100 }, upkeep = 35, qualityBonus = 25, militaryBonus = 10 },
    royal_fletchery = { name = "Kraljevska puščičarna", cost = { gold = 4000, wood = 500, stone = 600, iron = 200 }, upkeep = 80, qualityBonus = 40, prestigeBonus = 15 },
}
Fletcher.woodStock = 20; Fletcher.metalStock = 10; Fletcher.featherStock = 15; Fletcher.oilStock = 5; Fletcher.poisonStock = 3; Fletcher.leatherStock = 5
Fletcher.productStock = {}; Fletcher.buildings = {}; Fletcher.fletcher = nil; Fletcher.activeMaking = {}; Fletcher.totalProducts = 0; Fletcher.dayTimer = 0
function Fletcher.init() Fletcher.woodStock=20; Fletcher.metalStock=10; Fletcher.featherStock=15; Fletcher.oilStock=5; Fletcher.poisonStock=3; Fletcher.leatherStock=5; Fletcher.productStock={}; Fletcher.buildings={}; Fletcher.fletcher=nil; Fletcher.activeMaking={}; Fletcher.totalProducts=0; Fletcher.dayTimer=0; print("[Fletcher] Royal Fletcher & Arrow Maker System initialized (6 products, 4 buildings)") end
function Fletcher.hireFletcher(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Fletcher.fletcher={name=n or ("Puščičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Puščičar najet: %s (spretnost: %d)",Fletcher.fletcher.name,s),"success") end; return true end
function Fletcher.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Fletcher.build(id) local ok,e=Fletcher.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Fletcher.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Fletcher.getQualityBonus() local b=0; for _,bd in ipairs(Fletcher.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Fletcher.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and Fletcher.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.metalCost and Fletcher.metalStock<(d.metalCost or 0) then return false,"Premalo kovine" end; if d.featherCost and Fletcher.featherStock<(d.featherCost or 0) then return false,"Premalo perja" end; if d.oilCost and Fletcher.oilStock<(d.oilCost or 0) then return false,"Premalo olja" end; if d.poisonCost and Fletcher.poisonStock<(d.poisonCost or 0) then return false,"Premalo strupa" end; if d.leatherCost and Fletcher.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if #Fletcher.buildings==0 then return false,"Potrebna delavnica" end; if not Fletcher.fletcher then return false,"Potreben puščičar" end; return true end
function Fletcher.make(pt,qty) qty=qty or 10; local ok,e=Fletcher.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then Fletcher.woodStock=Fletcher.woodStock-d.woodCost*qty end; if d.metalCost then Fletcher.metalStock=Fletcher.metalStock-d.metalCost*qty end; if d.featherCost then Fletcher.featherStock=Fletcher.featherStock-d.featherCost*qty end; if d.oilCost then Fletcher.oilStock=Fletcher.oilStock-d.oilCost*qty end; if d.poisonCost then Fletcher.poisonStock=Fletcher.poisonStock-d.poisonCost*qty end; if d.leatherCost then Fletcher.leatherStock=Fletcher.leatherStock-d.leatherCost*qty end; local t=d.time; if Fletcher.fletcher then t=math.max(1,t-math.floor(Fletcher.fletcher.skill/15)) end; table.insert(Fletcher.activeMaking,{id="arrow_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,quantity=qty,cost=d.cost*qty,attack=d.attack or 0,armorPierce=d.armorPierce or 0,fireDamage=d.fireDamage or 0,poisonDamage=d.poisonDamage or 0,capacity=d.capacity or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function Fletcher.completeMaking(m) local q=1.0+(Fletcher.getQualityBonus()/100); if Fletcher.fletcher then q=q+(Fletcher.fletcher.skill/200) end; q=math.min(2.0,q); Fletcher.productStock[m.productType]=(Fletcher.productStock[m.productType] or 0)+m.quantity; Fletcher.totalProducts=Fletcher.totalProducts+m.quantity; if Fletcher.fletcher then Fletcher.fletcher.itemsMade=Fletcher.fletcher.itemsMade+m.quantity; if math.random()<0.15 then Fletcher.fletcher.skill=math.min(100,Fletcher.fletcher.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Puščice izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function Fletcher.update(dt) if not _G.state then return end; Fletcher.dayTimer=Fletcher.dayTimer+dt; if Fletcher.dayTimer>=30 then Fletcher.dayTimer=0; for i=#Fletcher.activeMaking,1,-1 do local m=Fletcher.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Fletcher.completeMaking(m); table.remove(Fletcher.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Fletcher.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Fletcher.fletcher then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Fletcher.getStats() return {woodStock=Fletcher.woodStock,metalStock=Fletcher.metalStock,featherStock=Fletcher.featherStock,productStock=Fletcher.productStock,numBuildings=#Fletcher.buildings,hasFletcher=Fletcher.fletcher~=nil,fletcherName=Fletcher.fletcher and Fletcher.fletcher.name or "—",fletcherSkill=Fletcher.fletcher and Fletcher.fletcher.skill or 0,activeMaking=#Fletcher.activeMaking,totalProducts=Fletcher.totalProducts} end
return Fletcher
